using System.Xml.Linq;
using ChartForgeX.Core;
using ChartForgeX.Primitives;
using ChartForgeX.Themes;
using ChartForgeX.VisualArtifacts;
using Xunit;
namespace ChartForgeX.Tests;
[Collection(nameof(FontRegistryCollection))]
public sealed class SequenceParticipantBandTests {
    [Theory] [InlineData(SequenceArtifactParticipantKind.Participant)] [InlineData(SequenceArtifactParticipantKind.Actor)]
    [InlineData(SequenceArtifactParticipantKind.Boundary)] [InlineData(SequenceArtifactParticipantKind.Control)]
    [InlineData(SequenceArtifactParticipantKind.Entity)] [InlineData(SequenceArtifactParticipantKind.Database)]
    [InlineData(SequenceArtifactParticipantKind.Collections)] [InlineData(SequenceArtifactParticipantKind.Queue)]
    public void AllNativeKindsUseOneMeasuredHeaderAndFooterAllocationWithContainedGlyphAndCompleteLabel(SequenceArtifactParticipantKind kind) {
        var model=Native(kind);model.Layout=new SequenceLayoutPolicy(participantBands:new SequenceParticipantBands(),mirrorParticipants:true);var prepared=model.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-"+kind,prepared);var header=prepared.Regions.Single(r=>r.Role=="sequence-participant"&&r.Id=="A");var glyph=prepared.Regions.Single(r=>r.Role=="sequence-participant-glyph"&&r.Id=="A");var label=prepared.Regions.Single(r=>r.Role=="sequence-participant-label"&&r.Id=="A");Inside(glyph.Bounds,header.Bounds);Inside(label.Bounds,header.Bounds);var footer=prepared.Regions.Single(r=>r.Role=="sequence-participant-footer"&&r.Id=="A");Inside(prepared.Regions.Single(r=>r.Role=="sequence-participant-footer-glyph"&&r.Id=="A").Bounds,footer.Bounds);Inside(prepared.Regions.Single(r=>r.Role=="sequence-participant-footer-label"&&r.Id=="A").Bounds,footer.Bounds);if(kind is not (SequenceArtifactParticipantKind.Participant or SequenceArtifactParticipantKind.Collections or SequenceArtifactParticipantKind.Queue)){var stereotype=prepared.Scene.Nodes.OfType<ChartForgeX.Rendering.VisualSceneText>().First(text=>text.Role=="sequence-participant-stereotype");Assert.Equal(6+stereotype.Text.Metrics.Height+4,label.Bounds.Top-glyph.Bounds.Bottom,8);Assert.Equal(6,header.Bounds.Bottom-label.Bounds.Bottom,8);}var svg=prepared.ToSvg();Assert.Contains("First",svg);Assert.Contains("Second",svg);Assert.DoesNotContain("…",svg);Assert.DoesNotContain("<script",svg);
    }
    [Fact] public void ShortAndMultilineIconLabelsEndAtTheSameLifelineDatum() {
        var model=Native(SequenceArtifactParticipantKind.Actor);model.Participants[0].Stereotype=null;model.Participants[1].Kind=SequenceArtifactParticipantKind.Control;model.Layout=new SequenceLayoutPolicy(participantBands:new SequenceParticipantBands());var prepared=model.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-datum",prepared);var labels=prepared.Regions.Where(r=>r.Role=="sequence-participant-label").ToArray();Assert.Equal(labels[0].Bounds.Bottom,labels[1].Bounds.Bottom,8);Assert.True(labels[0].Bounds.Top<labels[1].Bounds.Top);var glyphs=prepared.Regions.Where(r=>r.Role=="sequence-participant-glyph").ToArray();Assert.True(glyphs[0].Bounds.Bottom<glyphs[1].Bounds.Bottom);
    }
    [Theory] [InlineData(VisualThemeMode.Light)] [InlineData(VisualThemeMode.Dark)]
    public void NativeNullAndEmptyPoliciesKeepSvgPngAndPortableBytes(VisualThemeMode mode) {
        var model=Native(SequenceArtifactParticipantKind.Actor);model.ThemeMode=mode;var svg=model.ToSvg();var png=model.ToPng();var json=model.ToVisualArtifact().ToInterchangeJson();var first=model.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-null-"+mode,first);model.Layout=new SequenceLayoutPolicy();var second=model.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-empty-"+mode,second);Assert.Equal(svg,model.ToSvg());Assert.Equal(png,model.ToPng());Assert.Equal(json,model.ToVisualArtifact().ToInterchangeJson());Assert.Equal(first.ToSvg(),second.ToSvg());Assert.Equal(first.ToPng(),second.ToPng());Assert.DoesNotContain("participantBands",json);
    }
    [Fact] public void StyledParticipantAndActivationFactsRoundTripAndStayDetachedFromCallerMutations() {
        var model=Native(SequenceArtifactParticipantKind.Control);model.Layout=new SequenceLayoutPolicy(participantBands:new SequenceParticipantBands(48,9,7));var a=model.Participants[0];a.Border=ChartColor.FromHex("#123456");a.Fill=ChartColor.FromHex("#445566");a.ActivationFill=ChartColor.FromHex("#778899");a.ActivationBorder=ChartColor.FromHex("#aabbcc");model.Paint.FragmentTitleText=ChartColor.FromHex("#654321");model.AddActivation("A",true,0).AddActivation("A",false,1);var prepared=model.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-styled-first",prepared);var first=prepared.ToSvg();var json=prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeJson();var envelope=VisualArtifactInterchangeEnvelope.FromJson(json);Assert.Equal(2,envelope.Version);var restored=envelope.ToSequenceArtifact();Assert.Equal(48,restored.Layout!.ParticipantBands!.GlyphHeight);Assert.Equal(a.Border,restored.Participants[0].Border);Assert.Equal(a.ActivationFill,restored.Participants[0].ActivationFill);Assert.Equal(a.ActivationBorder,restored.Participants[0].ActivationBorder);Assert.Equal(model.Paint.FragmentTitleText,restored.Paint.FragmentTitleText);var again=restored.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-styled-restored",again);Assert.Equal(first,again.ToSvg());Assert.Equal(prepared.ToPng(),again.ToPng());a.Border=ChartColor.Black;a.ActivationFill=ChartColor.White;model.Layout=null;envelope.Nodes[0].Sequence!.Border="#000000";Assert.Equal(first,prepared.ToSvg());Assert.Equal(json,prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeJson());Assert.Contains("#778899",first);Assert.Contains("#AABBCC",first);
    }
    [Fact] public void EmptyVisibleViewRefillsWithoutLosingRawSourcePaintOrPreviouslyPreparedFacts() {
        var empty=SequenceArtifact.Create("empty-bands").WithSize(1100,500).AddParticipant("A","Review").AddParticipant("B","Archive");empty.Participants[0].Border=ChartColor.FromHex("#123456");empty.Layout=new SequenceLayoutPolicy(hideUnusedParticipants:true,participantBands:new SequenceParticipantBands());var before=empty.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-empty-view",before);var svg=before.ToSvg();Assert.DoesNotContain(before.Regions,r=>r.Role=="sequence-participant");empty.AddMessage("A","B","Save");var filled=empty.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-refill",filled);Assert.Equal(new[]{"A","B"},filled.Regions.Where(r=>r.Role=="sequence-participant").Select(r=>r.Id));Assert.Contains("#123456",filled.ToSvg());Assert.Equal(svg,before.ToSvg());Assert.Equal(2,before.ToArtifact(empty.Id,VisualArtifactKind.Sequence).ToInterchangeEnvelope().Nodes.Count);
    }
    [Fact] public void NonDefaultFieldsRequireV2AndMalformedOrTooSmallAllocationsRejectWithoutDroppingInk() {
        Assert.Throws<ArgumentOutOfRangeException>(()=>new SequenceParticipantBands(double.NaN));Assert.Throws<ArgumentOutOfRangeException>(()=>new SequenceParticipantBands(glyphLabelGap:-1));var model=Native(SequenceArtifactParticipantKind.Actor);model.Layout=new SequenceLayoutPolicy(participantBands:new SequenceParticipantBands());var json=model.ToVisualArtifact().ToInterchangeJson();Assert.Throws<NotSupportedException>(()=>VisualArtifactInterchangeEnvelope.FromJson(json.Replace("\"version\":2","\"version\":1",StringComparison.Ordinal)));Assert.Throws<ArgumentOutOfRangeException>(()=>VisualArtifactInterchangeEnvelope.FromJson(json.Replace("\"glyphHeight\":44","\"glyphHeight\":0",StringComparison.Ordinal)));model.Layout=new SequenceLayoutPolicy(participantBands:new SequenceParticipantBands(10));Assert.Throws<NotSupportedException>(()=>model.Prepare(SequencePresetFixture.Context()));
    }
    [Fact] public void BandedDestroyedFooterUsesTheSameTerminalLifelineAndRetainedLifetimeOwner() {
        var model=Native(SequenceArtifactParticipantKind.Actor);model.Participants[1].Kind=SequenceArtifactParticipantKind.Control;model.Participants[1].DestroyedAtMessageIndex=1;model.Layout=new SequenceLayoutPolicy(participantBands:new SequenceParticipantBands(),mirrorParticipants:true);var prepared=model.Prepare(SequencePresetFixture.Context());SequencePresetFixture.Capture("participant-bands-destruction",prepared);var footer=prepared.Regions.Single(r=>r.Role=="sequence-participant-footer"&&r.Id=="B");var line=prepared.Scene.Nodes.OfType<ChartForgeX.Rendering.VisualSceneLine>().Where(node=>node.Role=="sequence-lifeline").ElementAt(1);var facts=prepared.ToArtifact(model.Id,VisualArtifactKind.Sequence).ToInterchangeEnvelope();Assert.Equal(footer.Bounds.Top,line.End.Y,8);Assert.Equal(footer.Bounds.Y+footer.Bounds.Height/2,facts.Edges[1].ResolvedRoute[0].Y,8);Assert.DoesNotContain("sequence-destruction-cross",prepared.ToSvg());Assert.Equal(1,facts.Nodes.Single(n=>n.Id=="B").Sequence!.DestroyedAtMessageIndex);var restored=VisualArtifactInterchangeEnvelope.FromJson(facts.ToJson()).ToSequenceArtifact().Prepare(SequencePresetFixture.Context());Assert.Equal(prepared.ToSvg(),restored.ToSvg());Assert.Equal(prepared.ToPng(),restored.ToPng());
    }
    private static SequenceArtifact Native(SequenceArtifactParticipantKind kind){var model=SequenceArtifact.Create("participant-bands").WithSize(1100,800).AddParticipant("A","First\nSecond",kind).AddParticipant("B","Archive").AddMessage("A","B","Save").AddMessage("B","A","Done");model.Participants[0].Stereotype="service";return model;}
    private static void Inside(ChartRect inner,ChartRect outer){Assert.True(inner.Left>=outer.Left&&inner.Top>=outer.Top&&inner.Right<=outer.Right&&inner.Bottom<=outer.Bottom,$"{inner} is outside {outer}");}
}
